    QTest::newRow("utf8-then-ascii") << "%C3%A9%41" << u"\u00e9A"_s;

    // forbidden characters
    QTest::newRow("nul") << "/tmp/a%00b" << QString();
    QTest::newRow("nul-only") << "%00" << QString();
    QTest::newRow("slash") << "/tmp/a%2Fb" << QString();
    QTest::newRow("slash-lowercase") << "/tmp/a%2fb" << QString();
    QTest::newRow("slash-after-utf8") << "/tmp/%C3%A9%2F" << QString();
#ifdef Q_OS_WIN
    QTest::newRow("backslash") << "/tmp/a%5Cb" << QString();
    QTest::newRow("backslash-lowercase") << "/tmp/a%5cb" << QString();
#endif

    // overlong encodings of the forbidden characters
    QTest::newRow("overlong-nul") << "/tmp/%C0%80" << QString();
    QTest::newRow("overlong-slash-2") << "/tmp/%C0%AF" << QString();
    QTest::newRow("overlong-slash-3") << "/tmp/%E0%80%AF" << QString();
    QTest::newRow("overlong-slash-4") << "/tmp/%F0%80%80%AF" << QString();
    QTest::newRow("overlong-backslash") << "/tmp/%C1%9C" << QString();

    // invalid UTF-8
    QTest::newRow("lone-continuation") << "/tmp/%80" << QString();
    QTest::newRow("latin1") << "/tmp/%E9t%E9" << QString();
    QTest::newRow("truncated-2") << "/tmp/%C3" << QString();
    QTest::newRow("truncated-3") << "/tmp/%E2%82" << QString();
    QTest::newRow("truncated-before-ascii") << "/tmp/%E2%82x" << QString();
    QTest::newRow("truncated-before-percent") << "/tmp/%E2%82%41" << QString();
    QTest::newRow("surrogate") << "/tmp/%ED%A0%80" << QString();
    QTest::newRow("above-max") << "/tmp/%F4%90%80%80" << QString();
    QTest::newRow("bad-lead") << "/tmp/%FF" << QString();
}

void tst_QUrlInternal::decodeForLocalFile()
{
    QFETCH(QString, input);
    QFETCH(QString, expected);
    const QUrl::ComponentFormattingOptions mode = QUrl::FullyDecoded | QUrlDecodeForLocalFile;

    // prepend some data to be sure that it remains there
    const QString dataTag = QString::fromUtf8(QTest::currentDataTag());
    QString output = dataTag;

    const qsizetype result = qt_urlRecode(output, input, mode);
    if (expected.isNull()) {
        QCOMPARE_LT(result, 0);
        QCOMPARE(output, dataTag);
        return;
    }

    QCOMPARE_GE(result, 0);
    QCOMPARE(output.size(), dataTag.size() + result);
    if (result == 0)
        output += input;
    QCOMPARE(output, dataTag + expected);

    // the option has no effect unless combined with QUrl::FullyDecoded
    output.clear();
    QString control;
    if (!qt_urlRecode(output, input, QUrlDecodeForLocalFile))
        output = input;
    if (!qt_urlRecode(control, input, QUrl::PrettyDecoded))
        control = input;
    QCOMPARE(output, control);
}

void tst_QUrlInternal::decodeForLocalFileInvalidUtf8_data()
{
    QTest::addColumn<QByteArray>("utf8");
    QTest::addColumn<QString>("utf16");

    extern void loadInvalidUtf8Rows();
    loadInvalidUtf8Rows();
}

void tst_QUrlInternal::decodeForLocalFileInvalidUtf8()
{
    QFETCH(QByteArray, utf8);
    const QString input = QString::fromLatin1(utf8.toPercentEncoding());

    QString output = QTest::currentDataTag();
    QCOMPARE_LT(qt_urlRecode(output, input, QUrl::FullyDecoded | QUrlDecodeForLocalFile), 0);
    QCOMPARE(output, QTest::currentDataTag());
}

